-- supabase/seed/gujarat_locations.sql
-- Generated from packages/shared/src/data/gujarat-locations.json.
-- Covers all 33 districts of Gujarat, major cities, talukas, and prominent neighborhoods (219 entries).

begin;

on conflict (id) do update set
  name = excluded.name,
  display_name = excluded.display_name,
  district = excluded.district,
  location_type = excluded.location_type,
  lat = excluded.lat,
  lng = excluded.lng,
  geog = excluded.geog,
  aliases = excluded.aliases;

commit;
